+
+        Map<String, PipelineConfiguration> ingestPipelines = new HashMap<>();
+        for (Map.Entry<String, Integer> pipelineEntry : existingIngestPipelines.entrySet()) {
+            // we cannot mock PipelineConfiguration as it is a final class
+            ingestPipelines.put(
